#!/bin/sh
# gen_agents.sh - creates 100 project subagents: 50 general game-dev (game-*) + 50 Kingdoms Unfolded (ku-*)
set -e
export LC_ALL=C LANG=C
D='.opencode/agents'
mkdir -p "$D"
mk() {
  printf -- '---\ndescription: %s\nmode: subagent\npermission:\n  edit: %s\n  bash: %s\n---\n\n%s\n' "$4" "$2" "$3" "$5" > "$D/$1.md"
}

# ---------- 50 GENERAL GAME DEVELOPMENT ----------
mk 'game-mechanic-designer' 'deny' 'deny' 'Designs core loops, verbs, and rules for any genre. Use when inventing or tuning gameplay mechanics.' 'You are a game mechanics designer. Define player verbs, the core loop, fail states, and tuning levers in plain tables. Reference similar games for calibration and flag complexity costs before code exists.'
mk 'game-economy-balancer' 'deny' 'deny' 'Balances currencies, sinks, faucets, and pacing. Use for in-game economies and progression pacing.' 'You are a game economy balancer. Model faucets and sinks, compute time-to-earn curves, and propose sink adjustments that keep inflation flat without grinding.'
